use nu_glob::MatchOptions;
use std::path::Path;

fn main() {
    let cwd = std::env::args().nth(1).unwrap_or_else(|| "/tmp".into());
    for pat in [".", "./", "a.txt", "*"] {
        let mut paths = nu_glob::glob_with(pat, MatchOptions::default()).unwrap();
        println!("pattern {:?} initial scope {:?}", pat, {
            // no access; just print results without apply
            let v: Vec<_> = paths.by_ref().collect();
            v
        });
        let mut paths = nu_glob::glob_with(pat, MatchOptions::default()).unwrap();
        paths.apply_parent(Path::new(&cwd));
        let v: Vec<_> = paths.map(|p| p.map(|p| (p.clone(), p.strip_prefix(&cwd).map(|s| s.to_path_buf())))).collect();
        println!("  applied parent {:?}: {:?}", cwd, v);
    }
}

use nu_glob::MatchOptions;
use std::path::Path;

fn main() {
    let cwd = std::env::args().nth(1).unwrap_or_else(|| "/tmp".into());
    for pat in [".", "./", "a.txt", "*"] {
        let paths = nu_glob::glob_with(pat, MatchOptions::default()).unwrap();
        let v: Vec<_> = paths.collect();
        println!("pattern {:?} unapplied: {:?}", pat, v);
        let mut paths = nu_glob::glob_with(pat, MatchOptions::default()).unwrap();
        paths.apply_parent(Path::new(&cwd));
        let v: Vec<_> = paths
            .map(|p| p.map(|p| (p.clone(), p.strip_prefix(&cwd).map(|s| s.to_path_buf()))))
            .collect();
        println!("  applied parent {:?}: {:?}", cwd, v);
    }
}

